#!/usr/bin/env python3
"""Assistant B — verify stored coordinates (wit/*.npy, regenerated by gen_witness.py; not stored in the repository) with OWN code only (mylat.py):
lattice sites, consecutive beads bonded, injective, bridge (first bead strictly lowest, last bead highest in y),
and (h3,h8,h11,g) by two own counts (hash look-up of all integer displacements of squared norm 3, 8, 11 with
chain separation >= 3; k-d tree on the coordinates).  Prints one line per file and writes wit/verified.json.
"""
import sys, os, json, glob, time
sys.dont_write_bytecode = True
HERE = os.path.dirname(os.path.abspath(__file__))
import numpy as np
import mylat as ML

res = {}
for f in sorted(glob.glob(os.path.join(HERE, "wit", "*.npy"))):
    t0 = time.time()
    X = np.load(f).astype(np.int64)
    okw, okb = ML.check_walk_np(X)
    w = [tuple(int(c) for c in r) for r in X]
    hg1 = ML.profile_hash(w)
    hg2 = ML.profile_kdtree(w)
    # the slow scalar checks as well on the first and last 2000 beads
    assert ML.check_walk(w[:2000]) is None and ML.check_walk(w[-2000:]) is None
    N = len(w)
    name = os.path.basename(f)[:-4]
    ok = okw and okb and hg1 == hg2
    res[name] = dict(N=N, hg=list(hg1), ok=bool(ok))
    print(f"{name:34s} N = {N:6d}  walk {okw}  bridge {okb}  (h3,h8,h11,g) = {hg1}  two counts agree {hg1 == hg2}  "
          f"(h,g)/N = ({hg1[0]/N:.4f}, {hg1[1]/N:.4f}, {hg1[2]/N:.4f}; {hg1[3]/N:.4f})  168/(N+3) = {168/(N+3):.5f}  [{time.time()-t0:.1f} s]", flush=True)
json.dump(res, open(os.path.join(HERE, "wit", "verified.json"), "w"), indent=1)
